def diag_i2c_direccion(texto, bloque):
    try:
        direccion = int(str(texto).strip(), 0)
    except ValueError:
        direccion = -1
    if not 0 < direccion < 128:
        rb_fail(bloque, "Dirección I2C inválida: usa 0x08 a 0x77")
    return direccion

def diag_i2c_escanear(sda, scl, bloque):
    direcciones = i2c_bus(sda, scl, bloque).scan()
    for direccion in direcciones:
        print("I2C 0x%02X %s" % (direccion, DIAG_I2C_NOMBRES.get(direccion, "")))
    print("I2C: %d dispositivos" % len(direcciones))

def diag_i2c_hay(sda, scl, texto, bloque):
    return diag_i2c_direccion(texto, bloque) in i2c_bus(sda, scl, bloque).scan()

def diag_i2c_cantidad(sda, scl, bloque):
    return len(i2c_bus(sda, scl, bloque).scan())

