inline void diag_i2c_escanear(TwoWire& bus) {
    int cantidad = 0;
    for (uint8_t direccion = 1; direccion < 127; direccion++) {
        if (!diag_i2c_responde(bus, direccion)) continue;
        cantidad++;
        Serial.print("I2C 0x");
        if (direccion < 16) Serial.print("0");
        Serial.print(direccion, HEX);
        diag_i2c_nombre(direccion);
        Serial.println();
    }
    Serial.print("I2C: ");
    Serial.print(cantidad);
    Serial.println(" dispositivos");
}
inline int diag_i2c_direccion(const String& texto, const char* bloque) {
    const char* inicio = texto.c_str();
    char* fin = nullptr;
    long direccion = strtol(inicio, &fin, 0);
    if (fin == inicio || *fin != '\0' || direccion <= 0 || direccion >= 128) {
        rb_fail(bloque, "Dirección I2C inválida: usa 0x08 a 0x77");
        return 0;
    }
    return int(direccion);
}
inline bool diag_i2c_hay(TwoWire& bus, const String& texto, const char* bloque) {
    int direccion = diag_i2c_direccion(texto, bloque);
    return direccion > 0 && diag_i2c_responde(bus, uint8_t(direccion));
}
inline float diag_i2c_cantidad(TwoWire& bus) {
    int cantidad = 0;
    for (uint8_t direccion = 1; direccion < 127; direccion++)
        if (diag_i2c_responde(bus, direccion)) cantidad++;
    return float(cantidad);
}

